  ('formula.pc2.frost_vial_superior', NULL, 'Frasco Congelante Superior', 'Frost Vial Major', 'Vial de escarcha Superior', 'Causa 4d6 de frio e 4 de dano colateral; concede +3 no ataque e impõe –4,5 metros às Velocidades até o início do próximo turno.', 'Deals 4d6 cold damage and 4 cold splash damage; grants a +3 item attack bonus and imposes a –15-foot Speed penalty until the start of the next turn.', 'Inflige 4d6 de frío y 4 de daño colateral; concede +3 al ataque e impone –4,5 metros a las Velocidades hasta el inicio del próximo turno.', 15, 4, 17, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"2500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.acid_flask_moderate', NULL, 'Frasco de Ácido Moderada', 'Acid Flask Moderate', 'Frasco de ácido Moderada', 'Causa 2d6 de ácido persistente e 2 de dano colateral; concede +1 no ataque.', 'Deals 2d6 persistent acid damage and 2 acid splash damage; grants a +1 item attack bonus.', 'Inflige 2d6 de daño de ácido persistente y 2 de daño colateral; concede +1 al ataque.', 15, 4, 3, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"10 PO","needs_review":false}'::jsonb),
  ('formula.pc2.acid_flask_greater', NULL, 'Frasco de Ácido Maior', 'Acid Flask Greater', 'Frasco de ácido Mayor', 'Causa 3d6 de ácido persistente e 3 de dano colateral; concede +2 no ataque.', 'Deals 3d6 persistent acid damage and 3 acid splash damage; grants a +2 item attack bonus.', 'Inflige 3d6 de daño de ácido persistente y 3 de daño colateral; concede +2 al ataque.', 15, 4, 11, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"250 PO","needs_review":false}'::jsonb),
  ('formula.pc2.acid_flask_superior', NULL, 'Frasco de Ácido Superior', 'Acid Flask Major', 'Frasco de ácido Superior', 'Causa 4d6 de ácido persistente e 4 de dano colateral; concede +3 no ataque.', 'Deals 4d6 persistent acid damage and 4 acid splash damage; grants a +3 item attack bonus.', 'Inflige 4d6 de daño de ácido persistente y 4 de daño colateral; concede +3 al ataque.', 15, 4, 17, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"2500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.detonating_stone_moderate', NULL, 'Pedra Detonante Moderada', 'Detonating Stone Moderate', 'Piedra detonante Moderada', 'Causa 2d4 de sônico e 2 de dano colateral; concede +1 no ataque, CD 20, e pode ensurdecer criaturas próximas.', 'Deals 2d4 sonic damage and 2 sonic splash damage; grants a +1 item attack bonus, DC 20, and can deafen nearby creatures.', 'Inflige 2d4 de daño sónico y 2 de daño colateral; concede +1 al ataque, CD 20, y puede ensordecer a criaturas cercanas.', 15, 4, 3, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"10 PO","needs_review":false}'::jsonb),
  ('formula.pc2.detonating_stone_greater', NULL, 'Pedra Detonante Maior', 'Detonating Stone Greater', 'Piedra detonante Mayor', 'Causa 3d4 de sônico e 3 de dano colateral; concede +2 no ataque, CD 28, e pode ensurdecer criaturas próximas.', 'Deals 3d4 sonic damage and 3 sonic splash damage; grants a +2 item attack bonus, DC 28, and can deafen nearby creatures.', 'Inflige 3d4 de daño sónico y 3 de daño colateral; concede +2 al ataque, CD 28, y puede ensordecer a criaturas cercanas.', 15, 4, 11, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"250 PO","needs_review":false}'::jsonb),
  ('formula.pc2.detonating_stone_superior', NULL, 'Pedra Detonante Superior', 'Detonating Stone Major', 'Piedra detonante Superior', 'Causa 4d4 de sônico e 4 de dano colateral; concede +3 no ataque, CD 36, e pode ensurdecer criaturas próximas.', 'Deals 4d4 sonic damage and 4 sonic splash damage; grants a +3 item attack bonus, DC 36, and can deafen nearby creatures.', 'Inflige 4d4 de daño sónico y 4 de daño colateral; concede +3 al ataque, CD 36, y puede ensordecer a criaturas cercanas.', 15, 4, 17, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"2500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.bottled_lightning_moderate', NULL, 'Relâmpago Engarrafado Moderada', 'Bottled Lightning Moderate', 'Relámpago embotellado Moderada', 'Causa 2d6 de eletricidade e 2 de dano colateral; concede +1 no ataque e deixa o alvo desprevenido até o início do próximo turno.', 'Deals 2d6 electricity damage and 2 electricity splash damage; grants a +1 item attack bonus and makes the target off-guard until the start of the next turn.', 'Inflige 2d6 de electricidad y 2 de daño colateral; concede +1 al ataque y deja al objetivo desprevenido hasta el inicio del próximo turno.', 15, 4, 3, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"10 PO","needs_review":false}'::jsonb),
  ('formula.pc2.bottled_lightning_greater', NULL, 'Relâmpago Engarrafado Maior', 'Bottled Lightning Greater', 'Relámpago embotellado Mayor', 'Causa 3d6 de eletricidade e 3 de dano colateral; concede +2 no ataque e deixa o alvo desprevenido até o início do próximo turno.', 'Deals 3d6 electricity damage and 3 electricity splash damage; grants a +2 item attack bonus and makes the target off-guard until the start of the next turn.', 'Inflige 3d6 de electricidad y 3 de daño colateral; concede +2 al ataque y deja al objetivo desprevenido hasta el inicio del próximo turno.', 15, 4, 11, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"250 PO","needs_review":false}'::jsonb),
  ('formula.pc2.bottled_lightning_superior', NULL, 'Relâmpago Engarrafado Superior', 'Bottled Lightning Major', 'Relámpago embotellado Superior', 'Causa 4d6 de eletricidade e 4 de dano colateral; concede +3 no ataque e deixa o alvo desprevenido até o início do próximo turno.', 'Deals 4d6 electricity damage and 4 electricity splash damage; grants a +3 item attack bonus and makes the target off-guard until the start of the next turn.', 'Inflige 4d6 de electricidad y 4 de daño colateral; concede +3 al ataque y deja al objetivo desprevenido hasta el inicio del próximo turno.', 15, 4, 17, ARRAY['Alquímico', 'Consumível', 'Bomba']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 285, '{"category":"Alquímico (Bomba)","price":"2500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.bright_stick', NULL, 'Bastão Brilhante', 'Glow Rod', 'Bastón luminoso', 'Ao ser batido contra uma superfície dura, emite luz forte em 6 metros e luz fraca nos 12 metros seguintes por 6 horas.', 'When struck against a hard surface, it emits bright light in a 6-meter radius and dim light in the next 12 meters for 6 hours.', 'Al golpearlo contra una superficie dura, emite luz brillante en un radio de 6 metros y luz tenue en los 12 metros siguientes durante 6 horas.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Ferramenta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"category":"Alquímico (Ferramenta)","price":"3 PO","needs_review":false}'::jsonb),
  ('formula.pc2.smoke_ball', NULL, 'Bola de Fumaça', 'Smoke Ball', 'Bola de humo', 'Cria uma explosão de fumaça densa: criaturas na área ficam ocultadas, e a fumaça dura 1 minuto ou até ser dispersada por ventos fortes. Raio de 1,5 m; a versão maior tem raio de 3 m.', 'Creates a burst of dense smoke: creatures in the area are concealed, and the smoke lasts 1 minute or until dispersed by strong winds. The radius is 1.5 meters; the greater version has a 3-meter radius.', 'Crea una explosión de humo denso: las criaturas en el área quedan ocultas, y el humo dura 1 minuto o hasta que lo dispersen vientos fuertes. El radio es de 1,5 metros; la versión mayor tiene un radio de 3 metros.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Ferramenta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"category":"Alquímico (Ferramenta)","price":"3 PO","needs_review":false}'::jsonb),
  ('formula.pc2.forensic_dye', NULL, 'Corante Forense', 'Forensic Dye', 'Tinte forense', 'Ao receber uma pequena quantidade de outro composto ou material, como sangue ou lama, transforma-se rapidamente em substância marrom-avermelhada e depois volta a ficar transparente.', 'When given a small amount of another compound or material, such as blood or mud, it quickly turns brown-red and then becomes clear again.', 'Al añadir una pequeña cantidad de otro compuesto o material, como sangre o barro, se vuelve rápidamente marrón rojizo y luego vuelve a ser transparente.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Ferramenta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"category":"Alquímico (Ferramenta)","price":"3 PO","needs_review":false}'::jsonb),
  ('formula.pc2.phosphor', NULL, 'Fósforo', 'Phosphor', 'Fósforo', 'Ao ser esfregado contra uma superfície áspera, acende. Pode ser aceso e tocado em um objeto inflamável como parte da mesma ação de Interagir; permanece aceso por 1 rodada e então é consumido.', 'When rubbed against a rough surface, it ignites. It can be lit and touched to a flammable object as part of the same Interact action; it burns for 1 round and is then consumed.', 'Al frotarlo contra una superficie áspera, se enciende. Puede encenderse y tocar un objeto inflamable como parte de la misma acción de Interactuar; permanece encendido durante 1 asalto y luego se consume.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Ferramenta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"category":"Alquímico (Ferramenta)","price":"2 PL","needs_review":false}'::jsonb),
  ('formula.pc2.snake_oil', NULL, 'Óleo de Cobra', 'Snake Oil', 'Aceite de serpiente', 'Aplicado a um ferimento ou sintoma visível, faz o sintoma desaparecer por 1 hora e impede que a criatura sinta os efeitos da condição, embora eles permaneçam. Percepção CD 17 com Buscar detecta a farsa.', 'Applied to a wound or visible symptom, it makes the symptom disappear for 1 hour and prevents the creature from feeling the condition''s effects, although they remain. Perception DC 17 with Seek detects the deception.', 'Aplicado a una herida o síntoma visible, hace desaparecer el síntoma durante 1 hora y evita que la criatura sienta los efectos de la condición, aunque permanecen. Percepción CD 17 con Buscar detecta el engaño.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Ferramenta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 295, '{"category":"Alquímico (Ferramenta)","price":"2 PO","needs_review":false}'::jsonb),
  ('formula.pc2.ghost_ink', NULL, 'Tinta Fantasma', 'Ghost Ink', 'Tinta fantasmal', 'Fica transparente por 1 minuto após aplicada e brilha em vermelho quando exposta ao calor. O criador pode escolher luz solar, luz estelar, luz mágica ou luz alquímica sem calor como método de revelação.', 'It becomes transparent for 1 minute after application and glows red when exposed to heat. The creator can choose sunlight, starlight, magical light, or heatless alchemical light as the revealing method.', 'Se vuelve transparente durante 1 minuto tras aplicarla y brilla en rojo al exponerse al calor. El creador puede elegir luz solar, luz estelar, luz mágica o luz alquímica sin calor como método de revelación.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Ferramenta']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 296, '{"category":"Alquímico (Ferramenta)","price":"3 PO","needs_review":false}'::jsonb),
  ('formula.pc2.belladonna', NULL, 'Beladona', 'Belladonna', 'Belladona', 'Veneno ingerido com Fortitude CD 19, latência de 10 minutos e duração máxima de 30 minutos. Estágios: ofuscado por 10 minutos; 1d6 de veneno e enjoado 1 por 10 minutos; 1d6 de veneno, confuso e enjoado 1 por 1 minuto.', 'Ingested poison with Fortitude DC 19, a 10-minute onset, and a 30-minute maximum duration. Stages: dazzled for 10 minutes; 1d6 poison and sickened 1 for 10 minutes; 1d6 poison, confused, and sickened 1 for 1 minute.', 'Veneno ingerido con Fortaleza CD 19, latencia de 10 minutos y duración máxima de 30 minutos. Etapas: deslumbrado durante 10 minutos; 1d6 de veneno y enfermo 1 durante 10 minutos; 1d6 de veneno, confundido y enfermo 1 durante 1 minuto.', 15, 4, 2, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"category":"Alquímico (Veneno)","price":"5 PO","needs_review":false}'::jsonb),
  ('formula.pc2.arsenic', NULL, 'Arsênico', 'Arsenic', 'Arsénico', 'Veneno ingerido com Fortitude CD 18, latência de 10 minutos e duração máxima de 5 minutos. Estágios: 1d4 de veneno e enjoado 1; 1d6 de veneno e enjoado 2; 1d8 de veneno e enjoado 3.', 'Ingested poison with Fortitude DC 18, a 10-minute onset, and a 5-minute maximum duration. Stages: 1d4 poison and sickened 1; 1d6 poison and sickened 2; 1d8 poison and sickened 3.', 'Veneno ingerido con Fortaleza CD 18, latencia de 10 minutos y duración máxima de 5 minutos. Etapas: 1d4 de veneno y enfermo 1; 1d6 de veneno y enfermo 2; 1d8 de veneno y enfermo 3.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"category":"Alquímico (Veneno)","price":"3 PO","needs_review":false}'::jsonb),
  ('formula.pc2.giant_centipede_venom', NULL, 'Veneno de Centopeia Gigante', 'Giant Centipede Venom', 'Veneno de ciempiés gigante', 'Veneno de ferimento com Fortitude CD 17 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada: 1d4 de veneno; 1d4 de veneno e fatigado; 1d4 de veneno, desajeitado 1 e fatigado.', 'Injury poison with Fortitude DC 17 and a 6-round maximum duration. Each stage lasts 1 round: 1d4 poison; 1d4 poison and fatigued; 1d4 poison, clumsy 1, and fatigued.', 'Veneno de herida con Fortaleza CD 17 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto: 1d4 de veneno; 1d4 de veneno y fatigado; 1d4 de veneno, torpe 1 y fatigado.', 15, 4, 1, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"category":"Alquímico (Veneno)","price":"4 PO","needs_review":false}'::jsonb),
  ('formula.pc2.lethargy_poison', NULL, 'Veneno de Letargia', 'Lethargy Poison', 'Veneno de letargo', 'Veneno de ferimento com Fortitude CD 18 e duração máxima de 4 horas. Os estágios causam desacelerado 1, desacelerado 1, inconsciente e, no estágio 4, inconsciente por 1d4 horas.', 'Injury poison with Fortitude DC 18 and a 4-hour maximum duration. Stages cause slowed 1, slowed 1, unconscious, and at stage 4 unconscious for 1d4 hours.', 'Veneno de herida con Fortaleza CD 18 y duración máxima de 4 horas. Las etapas causan ralentizado 1, ralentizado 1, inconsciente y, en la etapa 4, inconsciente durante 1d4 horas.', 15, 4, 2, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"7 PO","needs_review":false}'::jsonb),
  ('formula.pc2.black_adder_venom', NULL, 'Veneno de Víbora Negra', 'Black Adder Venom', 'Veneno de víbora negra', 'Veneno de ferimento com Fortitude CD 18 e duração máxima de 3 rodadas. Cada estágio dura 1 rodada e causa 1d4, 1d6 ou 1d8 de dano de veneno.', 'Injury poison with Fortitude DC 18 and a 3-round maximum duration. Each stage lasts 1 round and deals 1d4, 1d6, or 1d8 poison damage.', 'Veneno de herida con Fortaleza CD 18 y duración máxima de 3 asaltos. Cada etapa dura 1 asalto e inflige 1d4, 1d6 o 1d8 de daño de veneno.', 15, 4, 2, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"6 PO","needs_review":false}'::jsonb),
  ('formula.pc2.cytillesh_oil', NULL, 'Óleo de Cytillesh', 'Cytillesh Oil', 'Aceite de cytillesh', 'Veneno com Fortitude CD 19 e duração máxima de 4 rodadas. Cada estágio dura 1 rodada e causa 1d8, 1d10 ou 2d8 de dano de veneno.', 'Poison with Fortitude DC 19 and a 4-round maximum duration. Each stage lasts 1 round and deals 1d8, 1d10, or 2d8 poison damage.', 'Veneno con Fortaleza CD 19 y duración máxima de 4 asaltos. Cada etapa dura 1 asalto e inflige 1d8, 1d10 o 2d8 de daño de veneno.', 15, 4, 3, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"10 PO","needs_review":false}'::jsonb),
  ('formula.pc2.grave_root', NULL, 'Raiz do Túmulo', 'Grave Root', 'Raíz de tumba', 'Veneno de ferimento com Fortitude CD 19 e duração máxima de 4 rodadas. Cada estágio dura 1 rodada: 1d8 de veneno; 1d10 de veneno e estupefato 1; 2d6 de veneno e estupefato 2.', 'Injury poison with Fortitude DC 19 and a 4-round maximum duration. Each stage lasts 1 round: 1d8 poison; 1d10 poison and stupefied 1; 2d6 poison and stupefied 2.', 'Veneno de herida con Fortaleza CD 19 y duración máxima de 4 asaltos. Cada etapa dura 1 asalto: 1d8 de veneno; 1d10 de veneno y estupefacto 1; 2d6 de veneno y estupefacto 2.', 15, 4, 3, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"category":"Alquímico (Veneno)","price":"10 PO","needs_review":false}'::jsonb),
  ('formula.pc2.spider_venom', NULL, 'Veneno de Aranha', 'Spider Venom', 'Veneno de araña', 'Veneno de ferimento com Fortitude CD 22 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada: 1d10 de veneno e enjoado 1; 1d12 de veneno, desajeitado 1 e enjoado 2; 2d6 de veneno, desajeitado 2 e enjoado 3.', 'Injury poison with Fortitude DC 22 and a 6-round maximum duration. Each stage lasts 1 round: 1d10 poison and sickened 1; 1d12 poison, clumsy 1, and sickened 2; 2d6 poison, clumsy 2, and sickened 3.', 'Veneno de herida con Fortaleza CD 22 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto: 1d10 de veneno y enfermo 1; 1d12 de veneno, torpe 1 y enfermo 2; 2d6 de veneno, torpe 2 y enfermo 3.', 15, 4, 5, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"category":"Alquímico (Veneno)","price":"25 PO","needs_review":false}'::jsonb),
  ('formula.pc2.giant_scorpion_venom', NULL, 'Veneno de Escorpião Gigante', 'Giant Scorpion Venom', 'Veneno de escorpión gigante', 'Veneno de ferimento com Fortitude CD 22 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada: 2d6 de veneno e enfraquecido 1; 2d8 de veneno e enfraquecido 1; 2d10 de veneno e enfraquecido 2.', 'Injury poison with Fortitude DC 22 and a 6-round maximum duration. Each stage lasts 1 round: 2d6 poison and enfeebled 1; 2d8 poison and enfeebled 1; 2d10 poison and enfeebled 2.', 'Veneno de herida con Fortaleza CD 22 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto: 2d6 de veneno y debilitado 1; 2d8 de veneno y debilitado 1; 2d10 de veneno y debilitado 2.', 15, 4, 6, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"40 PO","needs_review":false}'::jsonb),
  ('formula.pc2.rooting_toxin', NULL, 'Toxina de Enraizamento', 'Rooting Toxin', 'Toxina de enraizamiento', 'Veneno de contato com Fortitude CD 26, latência de 1 minuto e duração máxima de 6 minutos. Os estágios causam desajeitado 1/2/3 e penalidade de 3/6/9 metros em todas as Velocidades por 1 minuto.', 'Contact poison with Fortitude DC 26, a 1-minute onset, and a 6-minute maximum duration. Stages cause clumsy 1/2/3 and a 10/20/30-foot penalty to all Speeds for 1 minute.', 'Veneno de contacto con Fortaleza CD 26, latencia de 1 minuto y duración máxima de 6 minutos. Las etapas causan torpe 1/2/3 y una penalización de 3/6/9 metros a todas las Velocidades durante 1 minuto.', 15, 4, 7, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"category":"Alquímico (Veneno)","price":"55 PO","needs_review":false}'::jsonb),
  ('formula.pc2.nettleseed_residue', NULL, 'Resíduo de Urtiga', 'Nettleweed Residue', 'Residuo de ortiga', 'Veneno de contato com Fortitude CD 27, latência de 1 minuto e duração máxima de 6 minutos. Cada estágio dura 1 minuto e causa 3d6, 4d6 ou 6d6 de dano de veneno.', 'Contact poison with Fortitude DC 27, a 1-minute onset, and a 6-minute maximum duration. Each stage lasts 1 minute and deals 3d6, 4d6, or 6d6 poison damage.', 'Veneno de contacto con Fortaleza CD 27, latencia de 1 minuto y duración máxima de 6 minutos. Cada etapa dura 1 minuto e inflige 3d6, 4d6 o 6d6 de daño de veneno.', 15, 4, 8, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"category":"Alquímico (Veneno)","price":"75 PO","needs_review":false}'::jsonb),
  ('formula.pc2.wyvern_poison', NULL, 'Veneno de Wyvern', 'Wyvern Poison', 'Veneno de wyvern', 'Veneno de ferimento com Fortitude CD 26 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada e causa 3d6, 3d8 ou 3d10 de dano de veneno.', 'Injury poison with Fortitude DC 26 and a 6-round maximum duration. Each stage lasts 1 round and deals 3d6, 3d8, or 3d10 poison damage.', 'Veneno de herida con Fortaleza CD 26 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto e inflige 3d6, 3d8 o 3d10 de daño de veneno.', 15, 4, 8, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"category":"Alquímico (Veneno)","price":"80 PO","needs_review":false}'::jsonb),
  ('formula.pc2.weakening_powder', NULL, 'Pó Debilitante', 'Weakening Powder', 'Polvo debilitante', 'Veneno ingerido com Fortitude CD 28, latência de 10 minutos e duração máxima de 6 minutos. Os estágios causam fatigado; depois 5d6 de veneno e fatigado; por fim 6d6 de veneno, fatigado e paralisado.', 'Ingested poison with Fortitude DC 28, a 10-minute onset, and a 6-minute maximum duration. Stages cause fatigued; then 5d6 poison and fatigued; finally 6d6 poison, fatigued, and paralyzed.', 'Veneno ingerido con Fortaleza CD 28, latencia de 10 minutos y duración máxima de 6 minutos. Las etapas causan fatigado; luego 5d6 de veneno y fatigado; finalmente 6d6 de veneno, fatigado y paralizado.', 15, 4, 9, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"110 PO","needs_review":false}'::jsonb),
  ('formula.pc2.spider_root', NULL, 'Raiz de Aranha', 'Spider Root', 'Raíz de araña', 'Veneno de contato com Fortitude CD 28, latência de 1 minuto e duração máxima de 6 minutos. Cada estágio dura 1 minuto e causa 3d6/4d6/6d6 de veneno e desajeitado 1/2/3.', 'Contact poison with Fortitude DC 28, a 1-minute onset, and a 6-minute maximum duration. Each stage lasts 1 minute and deals 3d6/4d6/6d6 poison damage with clumsy 1/2/3.', 'Veneno de contacto con Fortaleza CD 28, latencia de 1 minuto y duración máxima de 6 minutos. Cada etapa dura 1 minuto e inflige 3d6/4d6/6d6 de veneno con torpe 1/2/3.', 15, 4, 9, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"110 PO","needs_review":false}'::jsonb),
  ('formula.pc2.aconite', NULL, 'Acônito', 'Aconite', 'Acónito', 'Veneno ingerido com Fortitude CD 30, latência de 10 minutos e duração máxima de 6 minutos. Estágios: 3d10, 4d10 ou 5d10 de dano de veneno por 1 minuto; sobreviver ao estágio 3 cura imediatamente a maldição de um teriantropo.', 'Ingested poison with Fortitude DC 30, a 10-minute onset, and a 6-minute maximum duration. Stages deal 3d10, 4d10, or 5d10 poison damage for 1 minute; surviving stage 3 immediately cures a lycanthrope curse.', 'Veneno ingerido con Fortaleza CD 30, latencia de 10 minutos y duración máxima de 6 minutos. Las etapas infligen 3d10, 4d10 o 5d10 de daño de veneno durante 1 minuto; sobrevivir a la etapa 3 cura inmediatamente la maldición de un licántropo.', 15, 4, 10, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"category":"Alquímico (Veneno)","price":"155 PO","needs_review":false}'::jsonb),
  ('formula.pc2.draining_shadow', NULL, 'Sombra Desgastante', 'Draining Shadow', 'Sombra agotadora', 'Veneno de ferimento CD 26; inflige dano de veneno e drena a vitalidade máxima.', 'Injury poison DC 26; inflicts poison damage and drains maximum vitality.', 'Veneno de herida CD 26; causa daño de veneno y drena la vitalidad máxima.', 15, 4, 10, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"category":"Alquímico (Veneno)","price":"160 PO","needs_review":false}'::jsonb),
  ('formula.pc2.black_lotus_extract', NULL, 'Extrato de Lótus Negra', 'Black Lotus Extract', 'Extracto de loto negro', 'Veneno ingerido com Fortitude CD 42, latência de 1 minuto e duração máxima de 6 rodadas. Estágios: 13d6, 15d6 ou 17d6 de dano de veneno, com drenado 1, drenado 1 ou drenado 2, respectivamente, por 1 rodada.', 'Ingested poison with Fortitude DC 42, a 1-minute onset, and a 6-round maximum duration. Stages deal 13d6, 15d6, or 17d6 poison damage with drained 1, drained 1, or drained 2 respectively, for 1 round.', 'Veneno ingerido con Fortaleza CD 42, latencia de 1 minuto y duración máxima de 6 asaltos. Las etapas infligen 13d6, 15d6 o 17d6 de daño de veneno con drenado 1, drenado 1 o drenado 2 respectivamente, durante 1 asalto.', 15, 4, 19, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"6500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.death_takings', NULL, 'Lágrimas da Morte', 'Tears of Death', 'Lágrimas de la muerte', 'Veneno ingerido com Fortitude CD 44, latência de 1 minuto e duração máxima de 10 minutos. Estágios: 20d6, 22d6 ou 24d6 de dano de veneno e paralisado por 1 rodada.', 'Ingested poison with Fortitude DC 44, a 1-minute onset, and a 10-minute maximum duration. Stages deal 20d6, 22d6, or 24d6 poison damage and paralyze for 1 round.', 'Veneno ingerido con Fortaleza CD 44, latencia de 1 minuto y duración máxima de 10 minutos. Las etapas infligen 20d6, 22d6 o 24d6 de daño de veneno y paralizan durante 1 asalto.', 15, 4, 20, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"12000 PO","needs_review":false}'::jsonb),
  ('formula.pc2.cave_worm_venom', NULL, 'Veneno de Vorme da Caverna', 'Cave Worm Venom', 'Veneno de gusano de caverna', 'Veneno de ferimento com Fortitude CD 32 e duração máxima de 6 rodadas. Cada estágio dura 1 rodada e causa 5d6, 6d6 ou 8d6 de veneno, sempre com enfraquecido 2.', 'Injury poison with Fortitude DC 32 and a 6-round maximum duration. Each stage lasts 1 round and deals 5d6, 6d6, or 8d6 poison damage, always with enfeebled 2.', 'Veneno de herida con Fortaleza CD 32 y duración máxima de 6 asaltos. Cada etapa dura 1 asalto e inflige 5d6, 6d6 u 8d6 de veneno, siempre con debilitado 2.', 15, 4, 12, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"category":"Alquímico (Veneno)","price":"500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.torpor_wine', NULL, 'Vinho de Torpor', 'Torpor Wine', 'Vino de sopor', 'Veneno ingerido com Fortitude CD 32, latência de 1 hora e duração máxima de 7 dias. Os estágios deixam a criatura inconsciente por 1, 2 ou 3 dias; enquanto durar, ela não pode acordar por nenhum meio.', 'Ingested poison with Fortitude DC 32, a 1-hour onset, and a 7-day maximum duration. Stages leave the creature unconscious for 1, 2, or 3 days; while it lasts, the creature cannot awaken by any means.', 'Veneno ingerido con Fortaleza CD 32, latencia de 1 hora y duración máxima de 7 días. Las etapas dejan a la criatura inconsciente durante 1, 2 o 3 días; mientras dure, no puede despertarse por ningún medio.', 15, 4, 12, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"category":"Alquímico (Veneno)","price":"325 PO","needs_review":false}'::jsonb),
  ('formula.pc2.hemlock', NULL, 'Cicuta', 'Hemlock', 'Cicuta', 'Veneno ingerido com Fortitude CD 38, latência de 30 minutos e duração máxima de 60 minutos. Cada estágio dura 10 minutos e causa 16d6/17d6/18d6 de veneno e enfraquecido 2/3/4.', 'Ingested poison with Fortitude DC 38, a 30-minute onset, and a 60-minute maximum duration. Each stage lasts 10 minutes and deals 16d6/17d6/18d6 poison damage with enfeebled 2/3/4.', 'Veneno ingerido con Fortaleza CD 38, latencia de 30 minutos y duración máxima de 60 minutos. Cada etapa dura 10 minutos e inflige 16d6/17d6/18d6 de veneno con debilitado 2/3/4.', 15, 4, 17, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"2250 PO","needs_review":false}'::jsonb),
  ('formula.pc2.death_cap_powder', NULL, 'Pó de Chapéu-da-Morte', 'Death Cap Powder', 'Polvo de sombrerillo de la muerte', 'Veneno ingerido com Fortitude CD 33, latência de 10 minutos e duração máxima de 6 minutos. Os estágios causam 7d8 de veneno; 9d6 de veneno e enjoado 2; 8d10 de veneno e enjoado 3.', 'Ingested poison with Fortitude DC 33, a 10-minute onset, and a 6-minute maximum duration. Stages deal 7d8 poison; 9d6 poison and sickened 2; 8d10 poison and sickened 3.', 'Veneno ingerido con Fortaleza CD 33, latencia de 10 minutos y duración máxima de 6 minutos. Las etapas infligen 7d8 de veneno; 9d6 de veneno y enfermo 2; 8d10 de veneno y enfermo 3.', 15, 4, 13, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"450 PO","needs_review":false}'::jsonb),
  ('formula.pc2.kings_sleep', NULL, 'Sono do Rei', 'King''s Sleep', 'Sueño del rey', 'Veneno ingerido virulento com Fortitude CD 41 e latência de 1 dia. Cada estágio dura 1 dia e causa drenado 1, drenado 1 ou drenado 2; a condição drenado é cumulativa e não pode ser removida enquanto o veneno durar.', 'Virulent ingested poison with Fortitude DC 41 and a 1-day onset. Each stage lasts 1 day and causes drained 1, drained 1, or drained 2; drained is cumulative and cannot be removed while the poison lasts.', 'Veneno ingerido virulento con Fortaleza CD 41 y latencia de 1 día. Cada etapa dura 1 día y causa drenado 1, drenado 1 o drenado 2; drenado es acumulativo y no puede eliminarse mientras dure el veneno.', 15, 4, 18, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"category":"Alquímico (Veneno)","price":"4000 PO","needs_review":false}'::jsonb),
  ('formula.pc2.cerulean_scourge', NULL, 'Flagelo Cerúleo', 'Cerulean Scourge', 'Flagelo cerúleo', 'Veneno de contato CD 22; causa dano de veneno, desajeitado e estupefato.', 'Contact poison DC 22; deals poison damage, clumsy, and stupefied.', 'Veneno de contacto CD 22; inflige daño de veneno, torpe y estupefacto.', 15, 4, 16, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"1450 PO","needs_review":false}'::jsonb),
  ('formula.pc2.sulfur_vapors', NULL, 'Vapores de Enxofre', 'Sulfur Vapors', 'Vapores de azufre', 'Veneno inalado CD 19; causa dano de veneno, ofuscamento e cegueira.', 'Inhaled poison DC 19; inflicts poison damage, dazzled, and blindness.', 'Veneno inhalado CD 19; causa daño de veneno, deslumbrado y ceguera.', 15, 4, 16, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 294, '{"category":"Alquímico (Veneno)","price":"1500 PO","needs_review":false}'::jsonb),
  ('formula.pc2.fogged_mind_mist', NULL, 'Bruma de Mente Enevoada', 'Fogged Mind Mist', 'Bruma de mente nublada', 'Veneno inalado que prejudica faculdades mentais; CD, dano e progressão devem ser conferidos no livro.', 'Inhaled poison that impairs mental faculties; check the book for DC, damage, and progression.', 'Veneno inhalado que perjudica las facultades mentales; verifica el libro para CD, daño y progresión.', 15, 4, 15, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 291, '{"category":"Alquímico (Veneno)","price":"1000 PO","needs_review":false}'::jsonb),
  ('formula.pc2.fear_flower_nectar', NULL, 'Néctar de Flor do Medo', 'Fearflower Nectar', 'Néctar de flor del miedo', 'Veneno ingerido CD 20; causa amedrontado progressivo, fuga e confusão.', 'Ingested poison DC 20; causes escalating fear, fleeing, and confusion.', 'Veneno ingerido CD 20; causa miedo progresivo, huida y confusión.', 15, 4, 4, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"16 PO","needs_review":false}'::jsonb),
  ('formula.pc2.inert_leg', NULL, 'Perna Inerte', 'Inert Leg', 'Pierna inerte', 'Prótese básica que restaura a mobilidade funcional do usuário.', 'Basic prosthetic restoring functional mobility to the wearer.', 'Prótesis básica que restaura la movilidad funcional del usuario.', 15, 4, 4, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 292, '{"category":"Alquímico (Veneno)","price":"15 PO","needs_review":false}'::jsonb),
  ('formula.pc2.pragardent_resin', NULL, 'Resina de Pragardente', 'Pragardent Resin', 'Resina de pragardente', 'Veneno de contato que causa dano persistente; CD e progressão devem ser conferidos na entrada do livro.', 'Contact poison that deals persistent damage; check the book entry for DC and progression.', 'Veneno de contacto que causa daño persistente; verifica la entrada para CD y progresión.', 15, 4, 11, ARRAY['Alquímico', 'Consumível', 'Veneno']::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 293, '{"category":"Alquímico (Veneno)","price":"225 PO","needs_review":false}'::jsonb)
insert into public.catalog_pets (id, name_pt, name_en, name_es, description_pt, description_en, description_es, pet_type, size, speed, attacks, traits, rarity, ruleset, source_book, source_page, data)
values
  ('pet.wolf', 'Lobo', 'Wolf Companion', 'Compañero lobo', 'Companheiro veloz que ajuda a flanquear e derrubar inimigos.', 'Fast companion that helps flank and trip enemies.', 'Compañero veloz que ayuda a flanquear y derribar enemigos.', 'animal_companion', 'Pequeno ou Médio', '40 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":6,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.bear', 'Urso', 'Bear Companion', 'Compañero oso', 'Companheiro resistente com mordidas e garras poderosas.', 'Durable companion with powerful jaws and claws.', 'Compañero resistente con poderosas mordidas y garras.', 'animal_companion', 'Pequeno ou Médio', '35 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":8,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.horse', 'Cavalo', 'Horse Companion / Mount', 'Compañero caballo / Montura', 'Montaria veloz para investidas e combate montado.', 'Fast mount for charges and mounted combat.', 'Montura veloz para cargas y combate montado.', 'animal_companion', 'Grande', '40 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":8,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.bird', 'Pássaro / Coruja', 'Bird Companion', 'Compañero ave', 'Companheiro voador ágil para reconhecimento e ataques precisos.', 'Agile flying companion for scouting and precise attacks.', 'Compañero volador ágil para explorar y atacar con precisión.', 'animal_companion', 'Pequeno', '10 pés, Voo 60 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":4,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.big_cat', 'Gato Grande / Pantera', 'Big Cat', 'Gran felino / Pantera', 'Companheiro furtivo que ajuda a deixar inimigos desprevenidos.', 'Stealthy companion that helps leave enemies off-guard.', 'Compañero sigiloso que ayuda a dejar desprevenidos a los enemigos.', 'animal_companion', 'Pequeno ou Médio', '35 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":6,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.dromaeosaur', 'Dromaeossauro', 'Dromaeosaur Companion', 'Compañero dromeosaurio', 'Companheiro veloz especializado em cercar e flanquear inimigos.', 'Fast companion specialized in surrounding and flanking enemies.', 'Compañero veloz especializado en rodear y flanquear enemigos.', 'animal_companion', 'Pequeno', '50 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 207, '{"hp_base":6,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.badger', 'Texugo', 'Badger Companion', 'Compañero tejón', 'Companheiro resistente que cava e causa dano contínuo.', 'Sturdy companion that burrows and deals persistent damage.', 'Compañero resistente que excava y causa daño persistente.', 'animal_companion', 'Pequeno', '25 pés, Escavação 10 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"hp_base":8,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.familiar', 'Familiar Arcano / Místico', 'Familiar', 'Familiar arcano / místico', 'Familiar que concede habilidades escolhidas ao seu mestre.', 'A familiar that grants chosen abilities to its master.', 'Familiar que concede habilidades elegidas a su amo.', 'animal_companion', 'Minúsculo', '25 pés', '[]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 212, '{"hp_base":5,"support_benefit":null,"advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.antelope', 'Antílope', 'Antelope', 'Antílope', 'Companheiro veloz e montável que pode causar sangramento persistente.', 'A swift mount companion that can cause persistent bleed damage.', 'Compañero veloz y montable que puede causar daño persistente por sangrado.', 'animal_companion', 'Médio ou Grande', '40 pés', '[{"name":"Chifres","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Casco","bonus":"—","damage":"1d4 impacto","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 91, '{"hp_base":6,"support_benefit":"Enquanto montado, Golpes que causam dano no alcance do antílope também causam 1d6 de sangramento persistente até o início do seu próximo turno.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.elk', 'Alce', 'Elk', 'Alce', 'Companheiro montável que intimida inimigos com seus chifres.', 'A mount companion that frightens enemies with its antlers.', 'Compañero montable que asusta a los enemigos con sus astas.', 'animal_companion', 'Médio ou Grande', '30 pés', '[{"name":"Chifres","bonus":"—","damage":"1d8 perfurante","traits":[]},{"name":"Casco","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 91, '{"hp_base":8,"support_benefit":"Até o início do seu próximo turno, se você atingir e causar dano a uma criatura no alcance do alce, ela fica Amedrontada 1.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.flying_squirrel', 'Esquilo Voador', 'Flying Squirrel', 'Ardilla voladora', 'Companheiro que plana e dificulta o deslocamento dos inimigos.', 'A companion that glides and hampers enemy movement.', 'Compañero que planea y dificulta el movimiento enemigo.', 'animal_companion', 'Pequeno', '25 pés, escalada 25 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"hp_base":6,"support_benefit":"Até o fim do seu próximo turno, um alvo atingido por seu Golpe no alcance do esquilo sofre –10 pés de penalidade de circunstância em seus Deslocamentos por 1 rodada.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.giraffe', 'Girafa', 'Giraffe', 'Jirafa', 'Companheiro montável de pescoço longo que amplia manobras de Empurrar.', 'A long-necked mount that improves Shove maneuvers.', 'Montura de cuello largo que mejora las maniobras de Empujar.', 'animal_companion', 'Grande', '35 pés', '[{"name":"Casco","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]},{"name":"Pescoço","bonus":"—","damage":"1d4 impacto","traits":["Não-Letal","Alcance 10 pés"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"hp_base":8,"support_benefit":"Enquanto montado na girafa, você não precisa de uma mão livre para Empurrar e um inimigo Empurrado move 10 pés (15 pés em sucesso crítico).","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.kangaroo', 'Canguru', 'Kangaroo', 'Canguro', 'Companheiro saltador que combina mobilidade e ataques corporais.', 'A leaping companion combining mobility and natural attacks.', 'Compañero saltador que combina movilidad y ataques naturales.', 'animal_companion', 'Pequeno', '30 pés', '[{"name":"Pé","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, o canguru conta como estando em seu espaço ou em um espaço vazio a até 5 pés para determinar flanqueamento.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.mongoose', 'Mangusto', 'Mongoose', 'Mangosta', 'Companheiro ágil que protege criaturas próximas contra flanqueamento.', 'An agile companion that protects nearby creatures from flanking.', 'Compañero ágil que protege a criaturas cercanas contra el flanqueo.', 'animal_companion', 'Pequeno', '25 pés, escavação 10 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 93, '{"hp_base":4,"support_benefit":"Até o fim do seu próximo turno, criaturas adjacentes ao mangusto não podem flanquear você.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.salamander', 'Salamandra', 'Salamander', 'Salamandra', 'Companheiro anfíbio que secreta veneno e nada em águas rasas.', 'An amphibious companion that secretes poison and swims in shallow water.', 'Compañero anfibio que secreta veneno y nada en aguas poco profundas.', 'animal_companion', 'Pequeno', '20 pés, natação 10 pés', '[{"name":"Cauda","bonus":"—","damage":"1d6 impacto","traits":[]},{"name":"Mandíbulas","bonus":"—","damage":"1d4 perfurante","traits":[]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 93, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, uma criatura adjacente que atingir você ou a salamandra sofre 1d6 de dano de veneno.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.giant_eel', 'Enguia Gigante', 'Giant Eel', 'Anguila gigante', 'Companheiro aquático avançado que cria ângulos inesperados para flanquear.', 'An advanced aquatic companion that creates unexpected flanking positions.', 'Compañero acuático avanzado que crea posiciones inesperadas de flanqueo.', 'animal_companion', 'Grande', '10 pés, natação 40 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d8 perfurante","traits":[]}]'::jsonb, ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 94, '{"hp_base":4,"support_benefit":"Até o início do seu próximo turno, para determinar flanqueamento a enguia pode contar como estando em seu espaço ou em um espaço vazio a até 10 pés, escolhendo um espaço diferente a cada ataque.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.giant_frog', 'Sapo Gigante', 'Giant Frog', 'Rana gigante', 'Companheiro anfíbio avançado com língua de longo alcance e controle de reações.', 'An advanced amphibious companion with a long-range tongue and reaction control.', 'Compañero anfibio avanzado con lengua de largo alcance y control de reacciones.', 'animal_companion', 'Grande', '20 pés, escalada 20 pés, natação 25 pés', '[{"name":"Mandíbulas","bonus":"—","damage":"1d8 perfurante","traits":[]},{"name":"Língua","bonus":"—","damage":"1d4 impacto","traits":["Alcance 15 pés"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 94, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, quando você atingir com sucesso uma criatura ameaçada pelo sapo, ela não pode usar reações acionadas por suas ações, a menos que seu nível seja maior que o seu.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.hippogriff', 'Hipogrifo', 'Hippogriff', 'Hipogrifo', 'Companheiro voador avançado para montaria e ataques aéreos.', 'An advanced flying companion for mounted and aerial attacks.', 'Compañero volador avanzado para ataques montados y aéreos.', 'animal_companion', 'Grande', '30 pés, voo 60 pés', '[{"name":"Bico","bonus":"—","damage":"1d6 perfurante","traits":[]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 95, '{"hp_base":8,"support_benefit":"Enquanto montado e após mover-se 10 pés ou mais antes de um Golpe corpo a corpo, adicione ao dano um bônus de circunstância igual ao dobro dos dados de dano da arma.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.riding_tarantula', 'Tarântula de Montaria', 'Riding Tarantula', 'Tarántula de monta', 'Companheiro aracnídeo avançado que escala e perturba ações de concentração.', 'An advanced arachnid companion that climbs and disrupts concentrate actions.', 'Compañero arácnido avanzado que trepa y perturba acciones de concentración.', 'animal_companion', 'Grande', '30 pés, escalada 30 pés', '[{"name":"Presas","bonus":"—","damage":"1d6 perfurante mais veneno","traits":["Acurada"]},{"name":"Perna","bonus":"—","damage":"1d4 perfurante","traits":["Ágil","Acurada"]}]'::jsonb, ARRAY[]::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"hp_base":4,"support_benefit":"Até o início do seu próximo turno, uma criatura atingida por seu Golpe que esteja no alcance da tarântula deve passar em um teste simples CD 5 ao usar uma ação de concentração ou perde a ação.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.roc', 'Roc', 'Roc', 'Roc', 'Companheiro voador colossal avançado capaz de carregar criaturas e empurrá-las.', 'A colossal advanced flying companion able to carry and push creatures.', 'Compañero volador colosal avanzado capaz de transportar y empujar criaturas.', 'animal_companion', 'Enorme', '15 pés, voo 60 pés', '[{"name":"Bico","bonus":"—","damage":"1d10 perfurante","traits":[]},{"name":"Garra","bonus":"—","damage":"1d8 cortante mais Agarrar","traits":["Ágil"]}]'::jsonb, ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"hp_base":8,"support_benefit":"Até o início do seu próximo turno, seus Golpes que causam dano a uma criatura ameaçada pelo roc empurram o alvo 5 pés para longe do roc.","advanced_maneuver":null,"needs_review":false}'::jsonb),
  ('pet.howl.umbrella_mushroom', 'Cogumelo Guarda-Chuva', 'Umbrella Mushroom', 'Hongo sombrilla', 'Companheiro fungo avançado que flutua e deixa inimigos estupefatos.', 'An advanced fungal companion that floats and leaves enemies stupefied.', 'Compañero fúngico avanzado que flota y deja a los enemigos estupefactos.', 'animal_companion', 'Grande', '15 pés, voo 30 pés', '[{"name":"Haste","bonus":"—","damage":"1d8 impacto","traits":[]}]'::jsonb, ARRAY[]::text[], 'uncommon', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"hp_base":6,"support_benefit":"Até o início do seu próximo turno, seus Golpes que causam dano a uma criatura no alcance do cogumelo deixam o alvo Estupefato 1 por 1 rodada; o efeito tem o traço veneno.","advanced_maneuver":null,"needs_review":false}'::jsonb),
